INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at)
SELECT 'AI-METER-AE-1: Workers Analytics Engine data point per AI call (qnfo-agents, qnfo-code-orchestrator, qnfo-research-exec)',
'Pillar cost, program QNFO.INFRA, roadmap RM-ANALYTICS-ENGINE-METERS-1 (source WORKERS-AI-SPEND-UNATTRIBUTED-RISING-1). Session-owned: the code loop cannot do it, because the binding is a wrangler.toml line (DENY_PATH in qnfo-code-orchestrator) and qnfo-agents ships as an esbuild bundle of src/ (npm ci && npm run build).
State on 2026-11-05: Workers Analytics Engine is live (dataset qnfo_fleet, binding FLEET_ANALYTICS in qnfo-observability, 15,868 points over 36 indexes) and the canonical deploy installs analytics_engine bindings (qnfo-ops installDeclaredBindings). What is missing is the per-call meter: one data point per Workers AI call in a dataset qnfo_ai_calls with index = worker, blobs = [purpose, model, outcome], doubles = [calls, in_tok, out_tok, cached_tok, neurons, ms], written fire-and-forget next to the existing ai_call_counters write, so attribution survives a D1 overload (d1AttrWriteSkip drops counter writes today) and is readable by AE SQL without touching qnfo-audit. Write sites: qnfo-agents/src/index.ts meter(), qnfo-code-orchestrator/worker.js ladder metering (the INSERT INTO ai_call_counters after the ledger write), qnfo-research-exec/worker.js __aiAttrBinding. Volume: about 4,000 calls a day, 120k points a month against 10M included. Each write is guarded by if (env.AI_METER) so a worker without the binding is unchanged.
Why not done in the C6-S1 slice: the three write sites were claimed by other sessions on 2026-11-05 (work-locks: qnfo-agents/src/index.ts C-ops-tools-F3, qnfo-code-orchestrator/worker.js c5-intel, qnfo-research-exec/worker.js C2-SCOUT). The attribution defect itself was closed without AE by the hourly ledger rollup (migration 2026-11-05-c6-s1-cost-views.sql). Take the work claims, add the [[analytics_engine_datasets]] binding AI_METER (dataset qnfo_ai_calls) to the three wrangler.toml files and the guarded writes, test with a fake binding, and verify with AE SQL: SELECT index1, sum(double5) FROM qnfo_ai_calls GROUP BY index1.
code-probe: {"paths": ["qnfo-code-orchestrator/worker.js"], "contains": "AI_METER.writeDataPoint"}',
'session:c6-s1', 'optimization', 'medium', 'open', CAST(strftime('%s', 'now') AS INTEGER) * 1000, CAST(strftime('%s', 'now') AS INTEGER) * 1000
WHERE NOT EXISTS (SELECT 1 FROM agent_issues WHERE title = 'AI-METER-AE-1: Workers Analytics Engine data point per AI call (qnfo-agents, qnfo-code-orchestrator, qnfo-research-exec)' AND status = 'open');

UPDATE roadmap_implementation SET status = 'partial', verified_at = datetime('now'),
  evidence = 'PARTIAL (C6-S1, PR 7414): the attribution defect behind this row is closed without Analytics Engine. Cause measured 2026-11-04: workers_ai_attribution_coverage_pct 33.9 because qnfo-agents (deepseek-v4.1-flash-1017 via the AI Gateway route dynamic/standard, meter 1,132,591 neurons and 7,126 requests that day) wrote tokens to ai_spend_ledger and never to ai_call_counters. Fix: the hourly D1 workflow ai-ledger-rollup (fleet_tasks + fleet_crons ai-ledger-rollup-hourly, :25) writes ai_call_counters rows worker qnfo-agents, purpose ledger-rollup, cache-aware neurons from cf_model_cached_price (945,613 neurons for the day from the ledger tokens, 83 percent of the meter; the rest is pre-ledger hours). Also wrapped with __aiAttrEnv: qnfo-email 2.12.5, qnfo-lifecycle 1.17.9. Analytics Engine per-call writes are NOT built: the dataset qnfo_fleet is live (qnfo-observability, 15,868 points) and the canonical deploy installs the binding, but the three write sites were claimed by other sessions, so the write is agent_issues AI-METER-AE-1 (session-owned, code-probe on qnfo-code-orchestrator/worker.js).'
  WHERE id = 56 AND item = 'RM-ANALYTICS-ENGINE-METERS-1' AND status <> 'partial';

UPDATE roadmap_implementation SET status = 'partial', verified_at = datetime('now'),
  evidence = 'PARTIAL (C6-S1, PR 7414): scripts/ai_call_paths_audit.mjs finds the 25 AI-calling workers by what their code does and classifies each path (binding, router, gateway, direct provider), scripts/ai-call-paths-audit.test.mjs fails an unmetered Workers AI caller or an unlisted provider host (DIRECT_ALLOW: qnfo-ai-calibration, personal-companion, qnfo-ai, qnfo-ops, each with its reason). It found four unmetered binding callers on 2026-11-05: qnfo-email and qnfo-lifecycle are wrapped (2.12.5, 1.17.9), qnfo-model-eval (6 sites) and qnfo-fleet-dashboard (2 sites) are on an expiring baseline (2026-11-12) with doers AI-METER-COVER-3a and 3b. Not covered: the per-path policy checks the 2026-10-01 audit left open inside qnfo-ops and qnfo-ai (streaming against non-streaming, the agent final round).'
  WHERE id = 17 AND item = 'RM-COST-FREE-FIRST-PARITY-1' AND status <> 'partial';

UPDATE roadmap_implementation SET status = 'partial', verified_at = datetime('now'),
  evidence = 'PARTIAL (C6-S1, PR 7414): v_cost_per_task_class (qnfo-audit, 14 days) gives USD per successful task for four paths and the dollars of every other counted worker. Read 2026-11-04 against live data: code loop USD 0.096 per merged PR on 11-03 and 11-04 (28 and 26 merges) against USD 0.16 to 1.73 on 10-30..11-02, research USD 0.76 to 1.36 per published paper on 11-01..11-04 (6 to 16 papers a day), qnfo-agents and the ops and ai routers from cost_router_metrics. Not covered: the outcome tables of q08, the gateway and personal paths live in other databases, so those rows carry dollars and no per-task figure (ok_tasks is NULL, the basis column says so).'
  WHERE id = 15 AND item = 'RM-COST-PER-TASK-ALL-PATHS-1' AND status <> 'partial';

UPDATE roadmap_implementation SET status = 'partial', verified_at = datetime('now'),
  evidence = 'PARTIAL (C6-S1, PR 7414): the draft-verify ladder is live on the code class and now measured per rung (v_ladder_rung_outcomes). Code loop 7 days to 2026-11-04: gpt-oss-120b (first rung) merged 73 tasks in 1,014 calls at USD 0.042 a merge, glm-5.3 merged 63 in 351 calls (USD 0.148), kimi-k2.7-code merged 36 in 713 calls (USD 0.793) and took 70 percent of the ladder dollars. Daily kimi calls fell 101 (11-02) to 46 (11-03) to 36 (11-04) and ladder neurons 653k to 225k a day (down 65 percent) after the cheap first rung and SPEND-ENFORCE-1. The extension beyond the code class (cheapest sufficient model per route, escalate on a failed check) is the spend governor, agent_issues 1001813 (ROADMAP-1 QNFO.INFRA #2174, in flight in the code loop).'
  WHERE id = 13 AND item = 'RM-COST-L6-DRAFT-VERIFY-1' AND status <> 'partial';

UPDATE roadmap_implementation SET status = 'retired', verified_at = datetime('now'),
  evidence = 'SUPERSEDED BY MEASUREMENT (C6-S1, PR 7414), not wontfix: v_distill_candidates (qnfo-audit, 7 days to 2026-11-04) ranks the recurring task classes by spend. The classes distillation fits best (short structured output) are small: the largest, q08-signal-engine kimi-k2.6, is 419 calls a week with 379 output tokens a call and USD 2.95 a week. The large classes are long-form research stages (16k input and 3 to 6k output tokens a call, USD 2.5 to 8 a week each) where a small LoRA model does not fit, the code-loop rungs (already routed cheap-first, row 13) and the qnfo-agents loop (USD 12 a day), which prefix caching, the 6-step cap and 2 asks per issue are cutting (row 14). A LoRA or exemplar bank would add input tokens or a paid fine-tune to a line that costs under USD 5 a week. Spend levers that move the USD 300 target live in agent_issues 1001675 (TOKEN-CUT-1, research neurons per publication 117k to 20k) and 1001813 (spend governor). Revisit rule: re-read v_distill_candidates and reopen if any class with avg_out_tok under 1000 exceeds USD 20 a week.'
  WHERE id = 12 AND item = 'RM-COST-L5-DISTILLATION-1' AND status <> 'retired';
